/** Write reviewed schedule cells by their exact reviewed bindings (target element id, parameter id, storage, read-only, hasValue, raw value) in one transaction. Stale, missing, blocked, or conflicting evidence refuses per cell; results keep the request cell index and each cell's own target index. */
export namespace ScheduleCellsApply {
  export namespace Req {
    export type RequestedParameterStorageType = "None" | "String" | "Integer" | "Double" | "ElementId";
    /**
     * Why a schedule cell has no writable parameter behind it.
     */
    export type ScheduleCellBindingBlocker =
      | "None"
      | "CalculatedField"
      | "CombinedParameterField"
      | "NonStandardDisplay"
      | "ParameterNotFound"
      | "ReadOnlyParameter";

    export interface Request {
      scheduleId: number;
      scheduleUniqueId: string;
      edits: ScheduleCellEdit[];
      dryRun?: boolean;
      transactionName?: null | string;
    }
    export interface ScheduleCellEdit {
      rowNumber: number;
      columnNumber: number;
      expectedBinding: ScheduleCellBinding;
      value?: null | string;
      unit?: null | string;
      rawInternal?: boolean;
    }
    /**
     * The write surface behind one rendered schedule cell: which element(s) a cell edit would
     * write to, and through which parameter. A type-parameter column resolves to the shared type
     * element, so TargetElementIds makes write fan-out explicit — one id shared by
     * every row of that type — instead of a per-instance surprise.
     *
     */
    export interface ScheduleCellBinding {
      columnNumber: number;
      targetElementIds: number[];
      parameterName?: null | string;
      parameterId?: number | null;
      storageType: RequestedParameterStorageType;
      rawValue?: null | string;
      displayValue?: null | string;
      isTypeParameter: boolean;
      isEditable: boolean;
      targets: ParameterTarget[];
      blocker?: ScheduleCellBindingBlocker;
      hasMixedValues?: boolean;
      displayUnit?: null | MeasuredDisplayUnit;
    }
    /**
     * Mutation evidence for one native parameter: what a reviewer saw, and what a writer compares against a fresh
     * read before writing. Schedule cells carry one per target; parameter edits carry one as Expected.
     *
     */
    export interface ParameterTarget {
      elementId: number;
      parameterId: number;
      parameterName?: null | string;
      storageType: RequestedParameterStorageType;
      isReadOnly: boolean;
      hasValue: boolean;
      rawValue: null | string;
    }
    /**
     * That a surface measures this value, and the unit it renders it in, read from the Reading's own
     * document (a schedule field's effective format options, else that document's units for the
     * spec). Every spelling is one the parameter unit door accepts, so a human surface can stage a
     * bare number with it. Null where nothing is measurable at all; TypeId null where it measures
     * but this document shows no unit — the surface asks for one instead of letting a push refuse a
     * bare number later. Refusal where Revit failed to answer, never read as not-measured. Evidence only: no write path fills a unit from it.
     *
     */
    export interface MeasuredDisplayUnit {
      specTypeId: string;
      typeId?: null | string;
      label?: null | string;
      symbol?: null | string;
      refusal?: null | string;
    }
  }
  export namespace Res {
    export type RequestedParameterStorageType = "None" | "String" | "Integer" | "Double" | "ElementId";
    /**
     * Why a schedule cell has no writable parameter behind it.
     */
    export type ScheduleCellBindingBlocker =
      | "None"
      | "CalculatedField"
      | "CombinedParameterField"
      | "NonStandardDisplay"
      | "ParameterNotFound"
      | "ReadOnlyParameter";
    /**
     * The closed set of reasons ParameterEditPlan refuses an edit; the prose stays the refusal's message.
     */
    export type EditRefusalCode =
      | "target-evidence-stale"
      | "target-evidence-missing"
      | "target-unresolved"
      | "admission-group-refused"
      | "alias-conflict";
    export type RevitDataIssueSeverity = "Info" | "Warning" | "Error";

    export interface Response {
      appliedCells: number;
      appliedParameterWrites: number;
      dryRun: boolean;
      results: ScheduleCellEditResult[];
      diagnostics: RevitDataIssue[];
    }
    export interface ScheduleCellEditResult {
      index: number;
      rowNumber: number;
      columnNumber: number;
      ok: boolean;
      error?: null | string;
      currentBinding?: null | ScheduleCellBinding;
      parameterResults: ParameterValueEditResult[];
      code?: null | EditRefusalCode;
      causeCode?: null | EditRefusalCode;
    }
    /**
     * The write surface behind one rendered schedule cell: which element(s) a cell edit would
     * write to, and through which parameter. A type-parameter column resolves to the shared type
     * element, so TargetElementIds makes write fan-out explicit — one id shared by
     * every row of that type — instead of a per-instance surprise.
     *
     */
    export interface ScheduleCellBinding {
      columnNumber: number;
      targetElementIds: number[];
      parameterName?: null | string;
      parameterId?: number | null;
      storageType: RequestedParameterStorageType;
      rawValue?: null | string;
      displayValue?: null | string;
      isTypeParameter: boolean;
      isEditable: boolean;
      targets: ParameterTarget[];
      blocker: ScheduleCellBindingBlocker;
      hasMixedValues: boolean;
      displayUnit?: null | MeasuredDisplayUnit;
    }
    /**
     * Mutation evidence for one native parameter: what a reviewer saw, and what a writer compares against a fresh
     * read before writing. Schedule cells carry one per target; parameter edits carry one as Expected.
     *
     */
    export interface ParameterTarget {
      elementId: number;
      parameterId: number;
      parameterName?: null | string;
      storageType: RequestedParameterStorageType;
      isReadOnly: boolean;
      hasValue: boolean;
      rawValue: null | string;
    }
    /**
     * That a surface measures this value, and the unit it renders it in, read from the Reading's own
     * document (a schedule field's effective format options, else that document's units for the
     * spec). Every spelling is one the parameter unit door accepts, so a human surface can stage a
     * bare number with it. Null where nothing is measurable at all; TypeId null where it measures
     * but this document shows no unit — the surface asks for one instead of letting a push refuse a
     * bare number later. Refusal where Revit failed to answer, never read as not-measured. Evidence only: no write path fills a unit from it.
     *
     */
    export interface MeasuredDisplayUnit {
      specTypeId: string;
      typeId?: null | string;
      label?: null | string;
      symbol?: null | string;
      refusal?: null | string;
    }
    export interface ParameterValueEditResult {
      index: number;
      ok: boolean;
      error?: null | string;
      parsedRaw?: null | string;
      parsedDisplay?: null | string;
      current?: null | ParameterTarget;
      code?: null | EditRefusalCode;
      causeCode?: null | EditRefusalCode;
    }
    export interface RevitDataIssue {
      code: string;
      severity: RevitDataIssueSeverity;
      message: string;
      familyName?: null | string;
      typeName?: null | string;
      parameterName?: null | string;
    }
  }
}

/** Execute trusted in-process C# in connected Revit: scriptContent for an inline snippet (Execute-body statements or a full PeScriptContainer class), or sourcePath for a captured src file in a valid pod workspace — exactly one of the two. sourceBundle may supply captured Pod manifest, project presence and source bytes with sourcePath; references resolve from the original workspace key. The supplied document is the script target; UI document and selection are available only when it is active. permissionMode defaults to ReadOnly, which discards supplied-document changes via a rollback guard; pass WriteTransaction for one host-owned transaction, or NoTransaction when the script or called library must own transaction boundaries (including APIs such as Document.SaveAs that reject an open transaction). */
export namespace ScriptingExecute {
  export namespace Req {
    export type ScriptPermissionMode = "ReadOnly" | "WriteTransaction" | "NoTransaction";

    export interface Request {
      scriptContent?: null | string;
      sourcePath?: null | string;
      workspaceKey?: string;
      sourceName?: null | string;
      permissionMode?: ScriptPermissionMode;
      timeoutSeconds?: number;
      sourceBundle?: null | ScriptPodSourceBundle;
    }
    export interface ScriptPodSourceBundle {
      files: ScriptPodSourceFile[];
    }
    export interface ScriptPodSourceFile {
      path: string;
      bytesBase64: string;
    }
  }
  export namespace Res {
    export type ScriptExecutionStatus =
      | "Succeeded"
      | "ReferenceResolutionFailed"
      | "CompilationFailed"
      | "RuntimeFailed"
      | "Rejected"
      | "PolicyRejected"
      | "Cancelled"
      | "TimedOut";
    export type ScriptDiagnosticSeverity = "Info" | "Warning" | "Error";
    /**
     * What a run's source was: a saved member's bytes, a supplied draft, or operation input with no member.
     */
    export type PodRunOrigin = "SavedMember" | "SuppliedDraft" | "Operation";
    /**
     * A run's settled outcome. Cancelled is its own answer, never a rollback claim.
     */
    export type PodRunOutcome = "Succeeded" | "Failed" | "Cancelled";

    export interface Response {
      status: ScriptExecutionStatus;
      output: string;
      diagnostics: ScriptDiagnostic[];
      revitVersion: string;
      targetFramework: string;
      containerTypeName?: null | string;
      executionId: string;
      artifacts?: ScriptArtifactData[] | null;
      data?: unknown;
      attribution?: null | PodReceipt;
    }
    export interface ScriptDiagnostic {
      stage: string;
      severity: ScriptDiagnosticSeverity;
      message: string;
      source?: null | string;
    }
    export interface ScriptArtifactData {
      name: string;
      relativePath: string;
      fullPath: string;
      contentType: string;
      sizeBytes: number;
    }
    /**
     * One run's receipt: its source origin, outcome, and outputs. `PodId` is null when an unfiled draft stores the run
     * in operation output.
     * `MemberSha256` names saved bytes, so only a SavedMember run carries it; a
     * supplied draft keeps the path it drafts and its own bytes and hash stay in `input.json`; operation input
     * names no member.
     *
     */
    export interface PodReceipt {
      podId?: null | string;
      memberPath?: null | string;
      memberSha256?: null | string;
      origin: PodRunOrigin;
      operation: string;
      planHash?: null | string;
      outcome: PodRunOutcome;
      outputs: string[];
      reason?: null | string;
    }
  }
}

